SA=system:serviceaccount:observability:prom-reader
check "ClusterRole monitoring aggregates rbac.example.com/aggregate-to-monitoring=true" bash -c "[ \"\$(kubectl --context main get clusterrole monitoring -o jsonpath='{.aggregationRule.clusterRoleSelectors[0].matchLabels.rbac\.example\.com/aggregate-to-monitoring}')\" = true ]"
check "prom-reader can list pods and nodes in all namespaces" bash -c "can_i main 'list pods -A' $SA && can_i main 'watch nodes' $SA && can_i main 'get pods/log -n kube-system' $SA"
check "prom-reader can list EndpointSlices through the aggregated role" bash -c "can_i main 'list endpointslices.discovery.k8s.io -A' $SA && kubectl --context main get clusterrole monitoring-view-endpoints -o jsonpath='{.metadata.labels}' | grep -q 'aggregate-to-monitoring'"
check "prom-reader can NOT read secrets or configmaps, and all original ClusterRoles still exist" bash -c "cannot_i main 'get secrets -n kube-system' $SA && cannot_i main 'list configmaps -A' $SA && kubectl --context main get clusterrole monitoring-debug monitoring-view-pods monitoring-view-nodes"
check "ClusterRoleBinding prom-reader-monitoring binds monitoring to the ServiceAccount" bash -c "[ \"\$(kubectl --context main get clusterrolebinding prom-reader-monitoring -o jsonpath='{.roleRef.name} {.subjects[0].kind} {.subjects[0].namespace} {.subjects[0].name}')\" = 'monitoring ServiceAccount observability prom-reader' ]"
